script:
frappe.ui.form.on('Project Portfolio', {
	refresh(frm) {
		if (frm.is_new()) return;

		frm.add_custom_button(__('Project Scoring Report'), () => {
			frappe.route_options = { project_portfolio: frm.doc.name };
			frappe.set_route('query-report', 'Project Scoring Report');
		}, __('View'));
	}
});
